{
  "items": [
    {
      "label": "FIGURE 3",
      "kind": "chart",
      "title": "Risks from extreme weather events are high and may increase without action",
      "bbox": [
        [485, 165, 715, 835]
      ],
      "content": {
        "panel_a": {
          "title": "a. Climate risks are high",
          "type": "bar chart",
          "y_axis": "Population (%)",
          "x_axis": "Regions (EAP, ECA, LAC, MNA, NAC, SAR, SSA)",
          "legend": [
            "Population exposed to extreme weather event",
            "Population exposed and vulnerable"
          ],
          "data_description": "Shows population percentages exposed to extreme weather events versus those exposed and vulnerable. SSA shows the highest proportion of exposed population being vulnerable (bars are nearly equal). SAR shows the highest total population at high risk (approx. 32%)."
        },
        "panel_b": {
          "title": "b. Greenhouse gas emissions reached record levels in 2022",
          "type": "stacked area chart",
          "y_axis": "GHG emissions (gt CO2e)",
          "x_axis": "Year (2000-2022)",
          "legend": [
            "SSA",
            "SAR",
            "NAC",
            "MNA",
            "LAC",
            "ECA",
            "EAP"
          ],
          "data_description": "Shows a steady increase in total global GHG emissions from 2000 to 2022, reaching a peak in 2022."
        },
        "sources": "Original figures for this publication based on World Bank calculations.",
        "notes": "GHG = greenhouse gas; gt CO2e = gigatons carbon dioxide equivalent; EAP = East Asia and Pacific; ECA = Europe and Central Asia; LAC = Latin America and the Caribbean; MNA = Middle East and North Africa; NAC = North America; SAR = South Asia; SSA = Sub-Saharan Africa. Panel a. Population exposed to extreme weather events, and the population at high risk from extreme weather events (exposed and vulnerable). Panel b. Total GHG emissions in gt CO2e."
      }
    }
  ]
}
